29	impl FormatRule<SourceComment<JsLanguage>> for FormatJsLeadingComment {
30	    type Context = JsFormatContext;
31	
32	    fn fmt(
33	        &self,
34	        comment: &SourceComment<JsLanguage>,
35	        f: &mut Formatter<Self::Context>,
36	    ) -> FormatResult<()> {
37	        if is_alignable_comment(comment.piece()) {
38	            let mut source_offset = comment.piece().text_range().start();
39	
40	            let mut lines = comment.piece().text().lines();
41	
42	            // SAFETY: Safe, `is_alignable_comment` only returns `true` for multiline comments
43	            let first_line = lines.next().unwrap();
44	            write!(f, [text(first_line.trim_end(), source_offset)])?;
45	
46	            source_offset += first_line.text_len();
47	
48	            // Indent the remaining lines by one space so that all `*` are aligned.
49	            write!(
50	                f,
51	                [&format_once(|f| {
52	                    for line in lines {
53	                        write!(
54	                            f,
55	                            [
56	                                hard_line_break(),
57	                                token(" "),
58	                                text(line.trim(), source_offset)
59	                            ]
60	                        )?;
61	
62	                        source_offset += line.text_len();
63	                    }
64	
65	                    Ok(())
66	                })]
67	            )
68	        } else {
69	            write!(f, [comment.piece().as_piece()])
70	        }
71	    }
72	}
